WITH with_windows AS (SELECT *, SUM(stock_qty) OVER (PARTITION BY supplier_id ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_stock_qty, AVG(stock_qty) OVER (PARTITION BY category ORDER BY stock_qty, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS stock_qty_avg_6, CORR(stock_qty, price) OVER (PARTITION BY supplier_id) AS corr_stock_qty_price FROM products) SELECT id, product_name, price, cost, stock_qty, launch_date, tags, running_stock_qty, corr_stock_qty_price FROM with_windows ORDER BY stock_qty DESC, corr_stock_qty_price DESC
